"""Generate packages/contracts/lead_sources.schema.json and lead_sources.ts from the models of the lead imports and sources (job DR / A2). Same scheme as the other contracts (`make contracts`; a test fails if a file is stale)."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.lead_sources import models as m
from app.packs.contracts import _ts_type

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/lead_sources/models.py. Do not edit.\n"
    "// Importing leads (file, Google Sheet, pasted list, vCard) and the live sources (website form, webhook, e-mail forwarding, Meta, IndiaMART).\n"
)
RESPONSES: list[type[BaseModel]] = [m.ReadOut, m.PreviewOut, m.ImportOut, m.ImportsOut, m.SourcesOut, m.SourceWithSecretOut, m.UnparsedListOut, m.IndiaMartPullOut, m.SheetLinkOut, m.SheetLinksOut, m.SheetAccessOut, m.TouchesOut, m.MailOut, m.ReceivedOut]
REQUESTS: list[type[BaseModel]] = [m.ReadIn, m.PreviewIn, m.ImportIn, m.SourceCreate, m.SheetLinkIn, m.MailIn]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema([(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}")
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "lead_sources.schema.json",
        "title": "Lead imports and sources (job DR / A2)",
        "description": "Generated from services/ai-api/app/lead_sources/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
